from collections import Counter
def find_ts(grid):
    h,w=len(grid),len(grid[0]); seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==2 and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and grid[nr][nc]==2 and not seen[nr][nc]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                comps.append(cells)
    out=[]
    for cells in comps:
        rc=Counter(r for r,c in cells)
        bar=[r for r,n in rc.items() if n==3][0]; stem=[r for r,n in rc.items() if n==1][0]
        out.append(stem<bar)
    return out

def transform(grid):
    ts=find_ts(grid)
    nu,nd=ts.count(True),ts.count(False)
    out=[[0]*6 for _ in range(3)]
    for i in range(nu): out[2*(i%2)][2*(i//2)]=3
    for i in range(nd): out[2*(i%2)][2*(i//2)+3]=1
    return out

